 * \brief Set the dequeue timeout value

int V4L2VideoDevice::releaseBuffers()
{
	if (!cache_)
		return 0;

	LOG(V4L2, Debug) << "Releasing buffers";

	cache_.reset();

	return requestBuffers(0, memoryType_);
}

/**
