template<typename EF>
class scope_exit
{
public:
	template<typename Fn,
		 std::enable_if_t<!std::is_same_v<std::remove_cv_t<std::remove_reference_t<Fn>>, scope_exit> &&
				  std::is_constructible_v<EF, Fn>> * = nullptr>
	explicit scope_exit(Fn &&fn)
		: exitFunction_(std::forward<Fn>(fn))
	{
		static_assert(std::is_nothrow_constructible_v<EF, Fn>);
	}

	~scope_exit()
	{
		if (active_)
			exitFunction_();
	}

	void release()
	{
		active_ = false;
	}

private:
	LIBCAMERA_DISABLE_COPY_AND_MOVE(scope_exit)

	EF exitFunction_;
	bool active_ = true;
};

template<typename EF>
scope_exit(EF) -> scope_exit<EF>;

void V4L2BufferCache::put(unsigned int index)
{
	ASSERT(index < cache_.size());
	cache_[index].free_ = true;
}

int PipelineHandlerUVC::queueRequestDevice(Camera *camera, Request *request)
{
	UVCCameraData *data = cameraData(camera);
	FrameBuffer *buffer = request->findBuffer(&data->stream_);
	if (!buffer) {
		LOG(UVC, Error)
			<< "Attempt to queue request with invalid stream";

		return -ENOENT;
	}

	int ret = processControls(data, request->controls());
	if (ret < 0)
		return ret;

	ret = data->video_->queueBuffer(buffer);
	if (ret < 0)
		return ret;

	return 0;
}

